init-job.yaml: |
  {{- if .Values.private.init.enabled }}
  apiVersion: batch/v1
  kind: Job
  metadata:
    name: {{ include "private.fullname" . }}-init
    annotations: {{ include "private.annotations" . | nindent 4 }}
  spec:
    template:
      spec:
        tolerations: {{ toYaml .Values.private.init.tolerations | nindent 8 }}
        affinity: {{ toYaml .Values.private.init.nodeAffinity | nindent 8 }}
        containers: ...
